// apiKeyAlphabet is the set of characters in an API key's random part.
const apiKeyAlphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

// newAPIKeyToken returns "tly_" followed by 40 characters from apiKeyAlphabet, drawn from crypto/rand. Bytes at or above
// 248 (the largest multiple of 62 below 256) are rejected so that every character is equally likely.
func newAPIKeyToken() string {
	const n = 40
	out := make([]byte, 0, n)
	buf := make([]byte, 64)
	for len(out) < n {
		if _, err := rand.Read(buf); err != nil {
			panic(err) // crypto/rand does not fail on supported platforms
		}
		for _, b := range buf {
			if b < 248 && len(out) < n {
				out = append(out, apiKeyAlphabet[int(b)%len(apiKeyAlphabet)])
			}
		}
	}
	return "tly_" + string(out)
}

