func TestAPIKeyStoresOnlyHash(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleMember, t0)
	k, err := s.CreateAPIKey(o.ID, u.ID, "CI", t0)
	if err != nil {
		t.Fatal(err)
	}
	if k.Token == "" || k.Last4 != k.Token[len(k.Token)-4:] || k.TokenHash != hashToken(k.Token) {
		t.Fatalf("created key = %+v", k)
	}
	stored, ok := s.APIKey(o.ID, k.ID)
	if !ok || stored.Token != "" || stored.TokenHash != hashToken(k.Token) || stored.Last4 != k.Last4 {
		t.Fatalf("stored key = %+v", stored)
	}
	if listed := s.APIKeys(o.ID); len(listed) != 1 || listed[0].Token != "" {
		t.Fatalf("listed keys = %+v", listed)
	}
	b, err := json.Marshal(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(b), k.Token) {
		t.Fatal("the export contains the full token")
	}
	if !strings.Contains(string(b), k.TokenHash) {
		t.Fatal("the export does not contain the token hash")
	}
}

