	}
	if got, ok := s.APIKeyByToken(legacy); !ok || got.ID != "key_000001" {
		t.Fatalf("the legacy key does not work: %+v %v", got, ok)
	}
	exported := s.Export()
	if k := exported.APIKeys[0]; k.Token != "" || k.TokenHash != hashToken(legacy) || k.Last4 != "0003" {
		t.Fatalf("migrated key = %+v", k)
	}
	s2, err := FromState(exported)
	if err != nil {
		t.Fatal(err)
	}
	if _, ok := s2.APIKeyByToken(legacy); !ok {
		t.Fatal("the migrated key does not work after the next save")
	}
	b, _ := json.Marshal(exported)
	if strings.Contains(string(b), legacy) {
		t.Fatal("the next snapshot contains the legacy token")
	}
}

func TestTouchAPIKeyIsThrottled(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleMember, t0)
	k, _ := s.CreateAPIKey(o.ID, u.ID, "CI", t0)
	s.TouchAPIKey(k.ID, t0)
	s.TouchAPIKey(k.ID, t0.Add(59*time.Second))
	if got, _ := s.APIKey(o.ID, k.ID); got.LastUsedAt == nil || !got.LastUsedAt.Equal(t0) {
		t.Fatalf("last use after 59s = %v", got.LastUsedAt)
	}
	s.TouchAPIKey(k.ID, t0.Add(60*time.Second))
	if got, _ := s.APIKey(o.ID, k.ID); got.LastUsedAt == nil || !got.LastUsedAt.Equal(t0.Add(60*time.Second)) {
		t.Fatalf("last use after 60s = %v", got.LastUsedAt)
	}
}

