func TestAPIKeyTokenIsShownOnce(t *testing.T) {
	e := apitest.New(t)
	var created struct {
		ID    string `json:"id"`
		Token string `json:"token"`
		Last4 string `json:"last4"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", e.Acme.Key, map[string]string{"name": "CI"}, &created)
	if !strings.HasPrefix(created.Token, "tly_") || created.Last4 != created.Token[len(created.Token)-4:] {
		t.Fatalf("created = %+v", created)
	}
	r := e.Do("GET", "/v1/api-keys", e.Acme.Key, nil)
	if strings.Contains(string(r.Body), created.Token) {
		t.Fatalf("the key list shows the token: %s", r.Body)
	}
	var list struct{ Items []map[string]any }
	if err := json.Unmarshal(r.Body, &list); err != nil {
		t.Fatal(err)
	}
	found := false
	for _, item := range list.Items {
		if _, ok := item["token"]; ok {
			t.Fatalf("the key list has a token field: %v", item)
		}
		if _, ok := item["token_hash"]; ok {
			t.Fatalf("the key list has a token hash field: %v", item)
		}
		if item["id"] == created.ID {
			found = true
			if item["last4"] != created.Last4 {
				t.Fatalf("listed last4 = %v", item["last4"])
			}
		}
	}
	if !found {
		t.Fatalf("the new key is not listed: %s", r.Body)
	}
}

