func TestSaveAfterLoadingPlainTextTokensWritesNoToken(t *testing.T) {
	const legacy = "tly_00000000000000000000000000000003"
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	old := `{"version": 2, "saved_at": "2026-01-01T00:00:00Z", "state": {"seq": 3, "api_keys": [` +
		`{"id": "key_000001", "org_id": "org_000001", "user_id": "usr_000001", "name": "old", "token": "` + legacy +
		`", "created_at": "2026-01-01T00:00:00Z"}]}}`
	dir := t.TempDir()
	oldPath := filepath.Join(dir, "old.json")
	if err := os.WriteFile(oldPath, []byte(old), 0o600); err != nil {
		t.Fatal(err)
	}
	st, err := Load(oldPath)
	if err != nil {
		t.Fatal(err)
	}
	if _, ok := st.APIKeyByToken(legacy); !ok {
		t.Fatal("a key from a plain-text snapshot does not work")
	}
	newPath := filepath.Join(dir, "new.json")
	if err := Save(st, newPath, now); err != nil {
		t.Fatal(err)
	}
	b, err := os.ReadFile(newPath)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(b), legacy) {
		t.Fatalf("the saved snapshot contains the plain-text token:\n%s", b)
	}
	reloaded, err := Load(newPath)
	if err != nil {
		t.Fatal(err)
	}
	if _, ok := reloaded.APIKeyByToken(legacy); !ok {
		t.Fatal("the key does not work after the next save")
	}
}

