// seed adds a demo organization with an owner and creates the owner's "Demo key" through the API. The API needs a key to
// authenticate that call, so the owner first gets a bootstrap key, held only in memory. Neither token is printed or
// logged; the log names the demo key by its last four characters.
func seed(st *store.Store, srv http.Handler, now time.Time, log *slog.Logger) (store.Org, error) {
	o, err := st.CreateOrg("Demo Co", store.OrgTeam, "UTC", 0, now)
	if err != nil {
		return store.Org{}, err
	}
	u, err := st.CreateUser("owner@demo.example", "Demo Owner", now)
	if err != nil {
		return store.Org{}, err
	}
	if _, err := st.AddMember(o.ID, u.ID, store.RoleOwner, now); err != nil {
		return store.Org{}, err
	}
	boot, err := st.CreateAPIKey(o.ID, u.ID, "Bootstrap key", now)
	if err != nil {
		return store.Org{}, err
	}
	req := httptest.NewRequest(http.MethodPost, "/v1/api-keys", strings.NewReader(`{"name":"Demo key"}`))
	req.Header.Set("Authorization", "Bearer "+boot.Token)
	rec := httptest.NewRecorder()
	srv.ServeHTTP(rec, req)
	if rec.Code != http.StatusCreated {
		return store.Org{}, fmt.Errorf("create demo key: status %d", rec.Code)
	}
	var k struct {
		Last4 string `json:"last4"`
	}
	if err := json.NewDecoder(rec.Body).Decode(&k); err != nil {
		return store.Org{}, fmt.Errorf("read demo key: %w", err)
	}
	log.Info("demo organization created", "org", o.ID, "api_key_last4", k.Last4)
	return o, nil
}

