package main

import (
	"bytes"
	"log/slog"
	"strings"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

func TestSeedCreatesDemoKeyThroughAPI(t *testing.T) {
	e := apitest.New(t)
	var logs bytes.Buffer
	log := slog.New(slog.NewTextHandler(&logs, nil))

	o, err := seed(e.Store, e.Server, e.Clock.Now(), log)
	if err != nil {
		t.Fatal(err)
	}

	keys := e.Store.APIKeys(o.ID)
	byName := map[string]store.APIKey{}
	for _, k := range keys {
		byName[k.Name] = k
	}
	demo, ok := byName["Demo key"]
	if !ok {
		t.Fatalf("demo org has keys %v, want a Demo key", keys)
	}
	// The bootstrap key authenticated the call to POST /v1/api-keys, so it was used.
	if boot := byName["Bootstrap key"]; boot.LastUsedAt == nil {
		t.Error("bootstrap key was not used: the demo key was not created through the API")
	}
	if !strings.Contains(logs.String(), "api_key_last4="+demo.Last4) {
		t.Errorf("log %q does not name the demo key by its last four characters", logs.String())
	}
	if strings.Contains(logs.String(), "tly_") {
		t.Errorf("log %q contains a token", logs.String())
	}
}

